def _wave19_identity_intact(path, text, root):
    # Validate raw current operands before syntax/body reconstruction. Complete
    # original line anchors and lexical kind refuse comments, stale aliases,
    # neighboring names and duplicate anchors. No broad body replacement.
    if root is None or not path.is_relative_to(root):
        return
    import hashlib
    from pathlib import Path
    manifest = ''.join('\t'.join(map(str, row[:-1])) + '\t' + str(int(row[-1])) + '\n'
                       for row in _WAVE19_IDENTITIES)
    valid = (len(_WAVE19_IDENTITIES) == 27
             and len({row[0] for row in _WAVE19_IDENTITIES}) == 27
             and hashlib.sha256(manifest.encode()).hexdigest() == _WAVE19_IDENTITY_PIN)
    _source_validity.append(valid)
    if not valid:
        raise ValueError('Wave19 frozen approved identity population')
    relative = path.relative_to(root).as_posix()
    for owner, old, new, spans in _WAVE19_COORDINATES:
        if relative == new:
            relative = old
            break
    selected_rows = [row for row in _WAVE19_IDENTITIES if row[1] == relative]
    if not selected_rows:
        return
    lexical = dspans_client.spans(text)
    states = {}
    for row in selected_rows:
        ident, logical, owner, target, anchor, offset, original, current, literal = row
        if owner not in states:
            states[owner] = _wave19_moved(root, owner)
            _wave19_coordinate(root / target, root)
        group = [member for member in selected_rows if member[4] == anchor]
        expected = anchor
        for member in sorted(group, key=lambda member: member[5], reverse=True):
            old_offset, old, new = member[5:8]
            valid = expected[old_offset:old_offset + len(old)] == old
            _source_validity.append(valid)
            if not valid:
                raise ValueError('Wave19 approved original anchor: ' + ident)
            if member[2] not in states:
                states[member[2]] = _wave19_moved(root, member[2])
                _wave19_coordinate(root / member[3], root)
            chosen = new if states[member[2]] else old
            expected = expected[:old_offset] + chosen + expected[old_offset + len(old):]
        valid = text.count(expected) == 1
        if valid:
            begin = text.index(expected)
            valid = ((begin == 0 or text[begin - 1] == '\n')
                     and (begin + len(expected) == len(text)
                          or text[begin + len(expected)] == '\n'))
        _source_validity.append(valid)
        if not valid:
            raise ValueError('Wave19 raw approved identity anchor: ' + ident)
        delta = sum(len(member[7]) - len(member[6]) for member in group
                    if member[5] < offset and states[member[2]])
        start = begin + offset + delta
        chosen = current if states[owner] else original
        end = start + len(chosen)
        in_string = any(a <= start and end <= b for a, b in lexical.strings)
        overlaps_comment = any(start < b and a < end for a, b in lexical.comments)
        valid = (text[start:end] == chosen and not overlaps_comment
                 and (in_string if literal else not in_string))
        _source_validity.append(valid)
        if not valid:
            raise ValueError('Wave19 raw approved identity lexical kind: ' + ident)


def _wave19_moved(root, owner):
    import json
    valid = (len(_WAVE19_OWNERS) == 26
             and len({row[0] for row in _WAVE19_OWNERS}) == 26
             and len(_WAVE19_COORDINATES) == 158
             and len({row[1] for row in _WAVE19_COORDINATES}) == 158
             and len({row[2] for row in _WAVE19_COORDINATES}) == 158)
    _source_validity.append(valid)
    if not valid:
        raise ValueError('Wave19 frozen owner/source coordinate population')
    _, old, new = next(row for row in _WAVE19_OWNERS if row[0] == owner)
    old, new = root / old / 'dub.json', root / new / 'dub.json'
    valid = old.is_file() != new.is_file()
    _source_validity.append(valid)
    if not valid:
        raise ValueError('Wave19 one selected recipe: ' + owner)
    moved = new.is_file()
    valid = json.loads((new if moved else old).read_text())['name'] == (
        owner if moved else 'vibe3d-' + owner)
    _source_validity.append(valid)
    if not valid:
        raise ValueError('Wave19 selected recipe identity: ' + owner)
    return moved


def _wave19_original(text, spans):
    for offset, current, original in reversed(spans):
        valid = text[offset:offset + len(current)] == current
        _source_validity.append(valid)
        if not valid:
            raise ValueError('Wave19 declaration/import coordinate')
        text = text[:offset] + original + text[offset + len(current):]
    return text


def _wave19_inventory_path(path, root):
    # Inventory omits a missing selected input so original floors refuse first.
    for owner, old, new, spans in _WAVE19_COORDINATES:
        if path in (root / old, root / new):
            return root / (new if _wave19_moved(root, owner) else old)
    return path


def _wave19_coordinate(path, root):
    if root is None:
        return None
    for owner, old, new, spans in _WAVE19_COORDINATES:
        if path not in (root / old, root / new):
            continue
        moved = _wave19_moved(root, owner)
        physical = root / (new if moved else old)
        valid = physical.is_file() and not (root / (old if moved else new)).exists()
        _source_validity.append(valid)
        if not valid:
            raise ValueError('Wave19 real source identity: ' + old)
        # The frozen first span is the module declaration, never an import.
        offset, current, original = spans[0]
        name = current if moved else original
        text = physical.read_text()
        # The original module token position is unchanged by its own rename.
        # Count all code declarations; comments and literals cannot supply one.
        import re
        lexical = dspans_client.spans(text)
        code = text
        for start, end in sorted(lexical.comments + lexical.strings, reverse=True):
            code = code[:start] + ' ' * (end - start) + code[end:]
        declarations = re.findall(r'\bmodule\b', code)
        valid = (code[offset - 7:offset] == 'module '
                 and code[offset:offset + len(name)] == name
                 and code[offset + len(name):offset + len(name) + 1] == ';'
                 and len(declarations) == 1)
        _source_validity.append(valid)
        if not valid:
            raise ValueError('Wave19 real declaration identity: ' + old)
        return physical, spans if moved else ()
    return None


def _wave19_import_original(path, text, root):
    if root is None or not path.is_relative_to(root):
        return text
    valid = (len(_WAVE19_CLIENT_IMPORTS) == 943
             and sum(map(len, _WAVE19_CLIENT_IMPORTS.values())) == 5098)
    _source_validity.append(valid)
    if not valid:
        raise ValueError('Wave19 frozen client/import coordinate population')
    _wave19_identity_intact(path, text, root)
    valid = (len(_WAVE19_COORDINATE_PRIOR_IMPORTS) == 37
             and sum(map(len, _WAVE19_COORDINATE_PRIOR_IMPORTS.values())) == 84
             and not set(_WAVE19_COORDINATE_PRIOR_IMPORTS) & set(_WAVE19_CLIENT_IMPORTS))
    _source_validity.append(valid)
    if not valid:
        raise ValueError('Wave19 old-coordinate prior import population')
    relative = path.relative_to(root).as_posix()
    imports = _WAVE19_CLIENT_IMPORTS.get(relative, _WAVE19_COORDINATE_PRIOR_IMPORTS.get(relative, ()))
    states, spans, delta = {}, [], 0
    for offset, current, original, owner in imports:
        if owner not in states:
            states[owner] = _wave19_moved(root, owner)
        selected = current if states[owner] else original
        spans.append((offset + delta, selected, original))
        delta += len(selected) - len(original)
    return _wave19_original(text, spans)


# Retain the pilot's private entry points for existing local callers.
def _math_moved(root):
    return _wave19_moved(root, 'math')


def _math_coordinate(path, root):
    return _wave19_coordinate(path, root)


def _math_original(text, spans):
    return _wave19_original(text, spans)


def _source_root(path, root=None):
    from pathlib import Path
    if root is not None:
        return Path(root).absolute()
    normal = Path(path).absolute()
    # Task 20262780: match the full owner before its trailing source component.
    # Keep lexical copy identity: owner and per-file links may omit one input.
    domains = {Path(owner).parts for owner in PRODUCTION_ROOTS}
    for owner, old, new in _WAVE19_OWNERS:
        for directory in (old, new):
            domains.add(Path(directory + '/source').parts)
            domains.add(Path(directory + '/tests/source').parts)
    domains.update(Path(relative).parent.parts for relative in _WAVE19_CLIENT_IMPORTS)
    relatives = [relative for pair in _SOURCE_MOVE_PINS for relative in pair]
    relatives += [destination for origin, ident, destination in _SOURCE_FRAGMENT_PINS]
    for relative in relatives:
        parts = Path(relative).parts
        end = parts.index('source') + 1 if 'source' in parts else 1
        domains.add(parts[:end])
    for parts in sorted(domains, key=lambda value: (-len(value), value)):
        for ancestor in (normal, *normal.parents):
            if ancestor.parts[-len(parts):] == parts:
                return ancestor.parents[len(parts) - 1]
    return None


def physical_source_path(path, *, root=None):
    from pathlib import Path
    path = Path(path).absolute()
    root = _source_root(path, root)
    math = _math_coordinate(path, root)
    if math is not None:
        return math[0]
    for old, new in SOURCE_MOVES:
        if root is not None and path == root / old:
            return path if path.exists() else physical_source_path(root / new, root=root)
    return path


def logical_source_paths(directory, pattern, *, root=None):
    from pathlib import Path
    directory = Path(directory)
    normal = directory.absolute()
    root = _source_root(normal, root)
    for owner, old_root, new_root in _WAVE19_OWNERS:
        if root is None or normal not in (root / old_root / 'source',
                                         root / old_root / 'tests/source'):
            continue
        moved = _wave19_moved(root, owner)
        result = []
        for coordinate_owner, old, new, spans in _WAVE19_COORDINATES:
            logical = root / old
            if (coordinate_owner == owner and logical.is_relative_to(normal)
                    and logical.match(pattern) and (root / (new if moved else old)).is_file()
                    and not any(destination == old for origin, destination in SOURCE_MOVES)):
                # Inventory is complete before any lexical declaration check;
                # read_source_text validates the selected input after its floors.
                result.append(logical)
        return result
    result = []
    for old, new in _SOURCE_MOVE_PINS:
        if root is not None:
            logical = root / old
            if logical.is_relative_to(normal) and logical.match(pattern):
                _source_validity.append((
                    sum(a == old for a, b in SOURCE_MOVES) == 1
                    and sum(a == old and b == new for a, b in SOURCE_MOVES) == 1
                    and logical.exists() != _wave19_inventory_path(root / new, root).exists()))
    for path in directory.rglob(pattern):
        if not any(root is not None and path.absolute() == root / new for old, new in SOURCE_MOVES):
            result.append(path)
    for old, new in SOURCE_MOVES:
        if root is not None:
            logical = root / old
            if logical.is_relative_to(normal) and logical.match(pattern) and _wave19_inventory_path(root / new, root).exists():
                result.append(directory / logical.relative_to(normal))
    return result


def _original_fragment(text, fragment):
    import hashlib
    if fragment['id'] == 'prepared_topology_pen_activation:UT1':
        text = text.replace('import toolpipe.state_paths : getStatePath;', 'import popup_state : getStatePath;')
    if fragment['id'] == 'ai3d.worker_manager:UT9':
        text = text.replace('enum repoRoot  = dirName(dirName(dirName(dirName(dirName(dirName(dirName(dirName(__FILE_FULL_PATH__))))))));',
                            'enum repoRoot  = dirName(dirName(dirName(__FILE_FULL_PATH__)));')
    if fragment['id'] == 'remesh.remesh_job:helper2':
        text = text.replace('version (unittest) public void tryRemove(string path)',
                            'version (unittest) private void tryRemove(string path)')
    declarations = ()
    if fragment['id'] == 'drag:helper2':
        declarations = ('immutable Cam[] corpusCams =', 'Viewport corpusViewport(',
                        'float vlen(', 'Vec3 exactPlaneDelta(')
    elif fragment['id'] == 'snap_render:helper6':
        declarations = ('float[16] t0619Matrix(', 'Viewport t0619Viewport(',
                        'Mesh t0619Mesh(', 'void t0619DrawnPx(', 'void t0619IdentityPx(',
                        'double t0619Dist(', 'ItemXform t0619Xf(', 'void t0619PxUnder(',
                        'Mesh t0619BgMeshA(', 'Mesh t0619BgMeshB(', 'void t0619InstallPrimary(')
    if any('\n    public ' + declaration in text for declaration in declarations):
        if any('\n    public ' + declaration not in text
               or '\n    private ' + declaration in text for declaration in declarations):
            return '', 0
        for declaration in declarations:
            text = text.replace('\n    public ' + declaration, '\n    private ' + declaration)
    encoded = text.encode('utf-8')
    prefix = fragment['prefix'].encode('utf-8')
    offset, matches, result = 0, 0, []
    while offset < len(encoded):
        found = encoded.find(prefix, offset)
        if found < 0:
            break
        part = encoded[found:found + fragment['length']]
        if len(part) == fragment['length'] and hashlib.sha256(part).hexdigest() == fragment['sha']:
            matches += 1
            result.append(part.decode('utf-8'))
        offset = found + 1
    return '\n'.join(result), matches




def _without_carrier_imports(source):
    import re
    # Only the named extracted imports are new; all original imports stay.
    names = '|'.join(re.escape(name) for name in _SOURCE_CARRIER_MODULES)
    return re.sub(r'\bimport\s+(?:' + names + r')\b[^;]*;',
                  lambda match: ''.join('\n' if c == '\n' else ' ' for c in match.group()), source)


def read_source_text(path, *, root=None, **kwargs):
    from pathlib import Path
    path = Path(path).absolute()
    root = _source_root(path, root)
    math = _math_coordinate(path, root)
    if math is not None:
        text = math[0].read_text(**kwargs)
        _wave19_identity_intact(math[0], text, root)
        return (_math_original(text, math[1]) if math[1] else
                _wave19_import_original(math[0], text, root))
    for old, new in _SOURCE_MOVE_PINS:
        if root is not None and path == root / old:
            _source_validity.append((sum(a == old for a, b in SOURCE_MOVES) == 1
                and sum(a == old and b == new for a, b in SOURCE_MOVES) == 1))
            _source_validity.append(all(
                sum(f['source'] == origin and f['id'] == ident and f['destination'] == destination
                    for f in SOURCE_FRAGMENTS) == 1
                for origin, ident, destination in _SOURCE_FRAGMENT_PINS if origin == old))
    for old, new in SOURCE_MOVES:
        if root is None or path != root / old:
            continue
        destination = root / new
        before, after = path.exists(), physical_source_path(destination, root=root).exists()
        physical = path if before else destination
        text = read_source_text(physical, root=root, **kwargs) if not before else (
            _wave19_import_original(physical, physical.read_text(**kwargs), root))
        if not before:
            text = _without_carrier_imports(text)
            if old == 'source/drag.d':
                context = 'version (unittest) {\n    import std.math : PI, sin, cos, tan;\n}\n'
                _source_validity.append(text.count(context) == 1)
                text = text.replace(context, '')
            if old == 'source/snap_render.d':
                context = 'version (unittest) {\n    import math     : lookAt, perspectiveMatrix, transformPoint;\n    import document : ItemXform, primaryModelSpaceResolver;\n    import std.format : format;\n}\n'
                _source_validity.append(text.count(context) == 1)
                text = text.replace(context, '')
            if old == 'source/ai/state.d':
                context = 'import toolpipe.state_paths : setStatePath;'
                _source_validity.append(text.count(context) == 1)
                text = text.replace(context, 'import popup_state : setStatePath;')
            if old == 'source/ai3d/worker_manager.d':
                context = '        enum repoRoot = dirName(dirName(dirName(dirName(dirName(__FILE_FULL_PATH__)))));'
                _source_validity.append(text.count(context) == 1)
                text = text.replace(context, '        enum repoRoot = dirName(dirName(dirName(__FILE_FULL_PATH__)));')
            if old == 'source/remesh/remesh_job.d':
                context = 'version (unittest) public void tryRemove(string path)'
                _source_validity.append(text.count(context) == 1)
                text = text.replace(context, 'version (unittest) private void tryRemove(string path)')
            if old == 'source/coord_rounding.d':
                text = text.replace('import toolpipe.state_paths : setStatePath;', 'import popup_state : setStatePath;')
        if not before:
            text = _restore_source_text(old, text, root)
        _source_validity.append(before != after)
        for fragment in SOURCE_FRAGMENTS:
            if fragment['source'] != old:
                continue
            if fragment in SOURCE_FRAGMENTS[-3:]:
                if before:
                    _, matches = _original_fragment(text, fragment)
                    _source_validity.append(matches == 1)
                continue
            if before:
                original, matches = _original_fragment(text, fragment)
            else:
                carrier = root / fragment['destination']
                original, matches = (_original_fragment(
                    _wave19_import_original(carrier, carrier.read_text(**kwargs), root), fragment)
                    if carrier.exists() else ('', 0))
                if fragment['destination'] != new:
                    text += '\n' + original
            _source_validity.append(matches == 1)
        return text
    text = _wave19_import_original(path, path.read_text(**kwargs), root)
    if root is not None and path.is_relative_to(root):
        text = _restore_source_text(str(path.relative_to(root)), text, root)
    return text


def source_input_start():
    return len(_source_validity)


def source_inputs_intact(first):
    return all(_source_validity[first:])
